using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BossesAchievementDataCustomDescription", menuName = "Data/Achievements/BossesAchievementDataCustomDescription")]
public class BossesAchievementDataCustomDescription : AchievementDataCustomDescription
{
	private const string customIdDescription = "DefeatEnemyAchievement";

	[SerializeField]
	[HideIf("hideNodeViewData")]
	private NodeViewData bossNodeViewData;

	[SerializeField]
	private bool enableBossNameID;

	[SerializeField]
	[ShowIf("enableBossNameID")]
	private string bossNameID;

	[SerializeField]
	private bool enableBossCorruptedAnimalData;

	[SerializeField]
	[ShowIf("enableBossCorruptedAnimalData")]
	private CorruptedAnimalData bossCorruptedAnimalData;

	private bool hideNodeViewData
	{
		get
		{
			if (!enableBossNameID)
			{
				return enableBossCorruptedAnimalData;
			}
			return true;
		}
	}

	public override string GetDescription(string idDescription)
	{
		string localizedString = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("DefeatEnemyAchievement");
		string arg = "";
		if (enableBossNameID)
		{
			arg = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(bossNameID);
		}
		else if (enableBossCorruptedAnimalData)
		{
			arg = bossCorruptedAnimalData.GetLocalizedName();
		}
		else if ((bool)bossNodeViewData.BossData)
		{
			arg = bossNodeViewData.BossData.GetLocalizedName();
		}
		else
		{
			Debug.Log("[ASTREA] MISSING BOSS DATA 3: " + base.name);
		}
		return string.Format(localizedString, arg);
	}
}
